func testAnswer(q []byte,typ uint16,body []byte)[]byte{r:=append([]byte(nil),q...);r[2]=0x81;r[3]=0x80;r[7]=1;r=append(r,0xc0,0x0c,byte(typ>>8),byte(typ),0,1,0,0,0,60,byte(len(body)>>8),byte(len(body)));return append(r,body...)}
func TestDNSResponse(t *testing.T){for _,c:=range []struct{typ uint16;body []byte;family int}{{1,[]byte{192,0,2,1},4},{28,make([]byte,16),6}}{q:=makeQuery("Example.COM",c.typ);r,e:=parseResponse(q,testAnswer(q,c.typ,c.body));if e!=nil||!r.Success||len(r.Addresses)!=1||r.Addresses[0].Family!=c.family||*r.MinTTL!=60{t.Fatalf("bad parse: %+v %v",r,e)}}}
func TestNegativeAndEmpty(t *testing.T){q:=makeQuery("example.com",1);for _,code:=range []byte{0,2,3,5}{b:=append([]byte(nil),q...);b[2]=0x81;b[3]=0x80|code;r,e:=parseResponse(q,b);if e!=nil||r.Success!=(code==0||code==3)||r.RCODE!=int(code){t.Fatalf("rcode%d %+v %v",code,r,e)}}}
func TestRejectMismatchAndMalformed(t *testing.T){q:=makeQuery("example.com",1);good:=testAnswer(q,1,[]byte{192,0,2,1});for _,mutate:=range []func([]byte)[]byte{func(b []byte)[]byte{b[0]^=1;return b},func(b []byte)[]byte{b[2]&=0x7f;return b},func(b []byte)[]byte{b[13]='X';return b},func(b []byte)[]byte{return b[:len(b)-1]},func(b []byte)[]byte{b[6]=0xff;return b},func(b []byte)[]byte{return append(b,0)}}{if _,e:=parseResponse(q,mutate(append([]byte(nil),good...)));e==nil{t.Fatal("accepted malformed/mismatched answer")}}}
func TestCompressionBounds(t *testing.T){for _,b:=range [][]byte{{0xc0,0},{0xc0,2,0},{0x40,0},{3,'a'}}{if _,_,e:=readName(b,0);e==nil{t.Fatal("accepted bad name")}};q:=makeQuery("example.com",1);b:=append(q,0xc0,12);n,e,err:=readName(b,len(q));if err!=nil||n!="example.com"||e!=len(b){t.Fatalf("compressed name: %s %d %v",n,e,err)}}
func TestQuestionCaseAndAllQTypes(t *testing.T){for _,typ:=range []uint16{1,28,15,16,33,65,255}{q:=makeQuery("example.com",typ);r:=append([]byte(nil),q...);r[2]=0x81;r[3]=0x80;r[13]='E';if _,e:=parseResponse(q,r);e!=nil{t.Fatal(e)}}}
func TestExtendedRCode(t *testing.T){q:=makeQuery("example.com",1);b:=append([]byte(nil),q...);b[2]=0x81;b[3]=0x80;b[11]=1;b=append(b,0,0,41,4,208,1,0,0,0,0,0);r,e:=parseResponse(q,b);if e!=nil||r.RCODE!=16||r.Success{t.Fatalf("extended code %+v %v",r,e)}}
func TestStatisticsBothOrNeither(t *testing.T){var s stats;r:=dnsResult{Success:true,WireSent:true,TransportResponse:true,RCODE:3,DurationMS:4,SendDelayMS:1};s.add(pairResult{Disposition:"sent",A:&r,B:&r});s.add(pairResult{Disposition:"unsent",Reason:"pair_queue_full"});if s.Arrivals!=2||s.Accepted!=1||s.Unsent!=1||s.A.Sent!=s.B.Sent||s.A.Sent!=1{t.Fatalf("unbalanced %+v",s)}}
func TestHistogramBounds(t *testing.T){var h histogram;for _,v:=range []float64{0.001,0.15,1,999.99,1000.1,9999.9,10000.1,99999.1,100001}{if bound(bucket(v))<v{t.Fatalf("bin below actual %f",v)};h.add(v)};if h.Count!=9||h.summary()["p99_sample_sufficient"]!=false{t.Fatal("wrong histogram")}}
func TestSiteHostProtection(t *testing.T){valid:=site{Host:"example.com",Path:"/test?q=1",Families:[]int{4,6}};if e:=validSite(valid);e!=nil{t.Fatal(e)};for _,host:=range []string{"", "127.0.0.1", "example.com:443","example.com@evil.test","example.com\r\nX: a","-x.test","x..test","x_test"}{s:=valid;s.Host=host;if validSite(s)==nil{t.Fatal("accepted bad host",host)}};for _,path:=range []string{"https://evil.test/","//evil.test/","relative","/\r\nX: y"}{s:=valid;s.Path=path;if validSite(s)==nil{t.Fatal("accepted bad path",path)}}}
func TestQueryWire(t *testing.T){q:=makeQuery("example.com",28);p,e:=parseQuestion(q);if e!=nil||p.Name!="example.com"||p.Type!=28||p.Class!=1||binary.BigEndian.Uint16(q[4:6])!=1{t.Fatal("bad generated query")}}
func TestHTTPSVerifiedFixedIPNoProxyNoRedirect(t *testing.T){hosts:=make(chan string,2);server:=httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){hosts<-r.Host;w.Header().Set("Location","https://unreachable.invalid/");w.WriteHeader(302);w.Write([]byte("hello"))}));defer server.Close();_,port,e:=net.SplitHostPort(strings.TrimPrefix(server.URL,"https://"));if e!=nil{t.Fatal(e)};roots:=x509.NewCertPool();roots.AddCert(server.Certificate());t.Setenv("HTTPS_PROXY","http://127.0.0.1:1");s:=site{Host:"example.com",Path:"/",Families:[]int{4}};r:=doHTTPS(context.Background(),s,"127.0.0.1",1024,httpsConfig{Roots:roots,Port:port});seenHost:="";select{case seenHost=<-hosts:default:};if !r.Success||r.Status!=302||seenHost!="example.com"||!r.CertificateVerified||!r.TLSHandshakeSuccess||!r.BodyComplete||r.BodyBytes!=5{t.Fatalf("HTTPS protection failure %+v host=%q",r,seenHost)};s.Host="wrong.invalid";r=doHTTPS(context.Background(),s,"127.0.0.1",1024,httpsConfig{Roots:roots,Port:port});if r.Success||r.CertificateVerified{t.Fatalf("accepted wrong certificate host %+v",r)}}
func TestHTTPSBodyBoundAndBindingFailure(t *testing.T){server:=httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Write([]byte(strings.Repeat("x",50)))}));defer server.Close();_,port,_:=net.SplitHostPort(strings.TrimPrefix(server.URL,"https://"));roots:=x509.NewCertPool();roots.AddCert(server.Certificate());s:=site{Host:"example.com",Path:"/",Families:[]int{4}};r:=doHTTPS(context.Background(),s,"127.0.0.1",10,httpsConfig{Roots:roots,Port:port});if !r.Success||!r.BodyLimited||r.BodyComplete||r.BodyBytes!=10{t.Fatalf("body limit %+v",r)};r=doHTTPS(context.Background(),s,"127.0.0.1",10,httpsConfig{Roots:roots,Port:port,Interface:"no-such-ab24"});if r.Success||r.TLSHandshakeSuccess||r.Error==""{t.Fatalf("binding failed open %+v",r)}}
func TestTruncationIsNotFullSuccess(t *testing.T){q:=makeQuery("example.com",1);b:=append([]byte(nil),q...);b[2]=0x83;b[3]=0x80;r,e:=parseResponse(q,b);if e!=nil||!r.Truncated||r.Success||r.Error!="truncated_response"{t.Fatalf("TC response %+v %v",r,e)}}
func TestFailedDialIsNotSent(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());cancel();r:=dnsQuery(ctx,"127.0.0.1:1","a","tcp",makeQuery("example.com",1),time.Now().UnixNano(),time.Second);var a armStats;a.add(r);if r.WireSent||r.TransportResponse||r.SentNS!=0||r.BytesWritten!=0||a.Attempted!=1||a.Sent!=0||a.Responses!=0{t.Fatalf("dial failure counted sent %+v %+v",r,a)}}
func TestSERVFAILIsTransportResponseNotTimeout(t *testing.T){server,e:=net.ListenPacket("udp","127.0.0.1:0");if e!=nil{t.Fatal(e)};defer server.Close();go func(){buf:=make([]byte,2048);n,a,e:=server.ReadFrom(buf);if e==nil{buf[2]=0x81;buf[3]=0x82;server.WriteTo(buf[:n],a)}}();r:=dnsQuery(context.Background(),server.LocalAddr().String(),"b","udp",makeQuery("example.com",1),time.Now().UnixNano(),time.Second);if !r.WireSent||!r.TransportResponse||r.Success||r.TimedOut||r.RCODE!=2||r.SendStartedMonoNS==0||r.FinishedMonoNS<r.SendStartedMonoNS{t.Fatalf("SERVFAIL accounting %+v",r)}}
func TestBoundedQueueAndBufferedEOF(t *testing.T){server,e:=net.ListenPacket("udp","127.0.0.1:0");if e!=nil{t.Fatal(e)};defer server.Close();go func(){buf:=make([]byte,2048);for{n,a,e:=server.ReadFrom(buf);if e!=nil{return};b:=append([]byte(nil),buf[:n]...);b[2]=0x81;b[3]=0x80;time.Sleep(5*time.Millisecond);server.WriteTo(b,a)}}();var input strings.Builder;enc:=json.NewEncoder(&input);for i:=0;i<200;i++{enc.Encode(captureEvent{Type:"dns_query",TS:time.Now().UnixNano(),Transport:"udp",Wire:base64.StdEncoding.EncodeToString(makeQuery("example.com",1)),Sequence:uint64(i+1)})};output:=filepath.Join(t.TempDir(),"results");e=run(context.Background(),options{A:server.LocalAddr().String(),B:server.LocalAddr().String(),Output:output,Duration:time.Second,Timeout:time.Second,MaxInflight:1,Queue:1,BodyLimit:1024},strings.NewReader(input.String()));if e!=nil{t.Fatal(e)};b,e:=os.ReadFile(filepath.Join(output,"final.json"));if e!=nil{t.Fatal(e)};var f struct{Complete bool `json:"complete"`;Input uint64 `json:"input_queries"`;Results struct{Accepted uint64 `json:"accepted_pairs"`;Unsent uint64 `json:"unsent_pairs"`;A struct{Sent uint64 `json:"sent"`} `json:"a"`;B struct{Sent uint64 `json:"sent"`} `json:"b"`} `json:"results"`};if e=json.Unmarshal(b,&f);e!=nil{t.Fatal(e)};if f.Complete||f.Input!=200||f.Results.Unsent==0||f.Results.Accepted+f.Results.Unsent!=200||f.Results.A.Sent!=f.Results.B.Sent||f.Results.A.Sent!=f.Results.Accepted{t.Fatalf("queue or EOF accounting %+v",f)}}
func TestFixtureSmoke(t *testing.T){if e:=fixtureSmoke();e!=nil{t.Fatal(e)}}
